import assert from 'node:assert/strict';
import {readFileSync} from 'node:fs';
import {createHash} from 'node:crypto';
import {Session} from 'node:inspector';
import {evaluateUnifiedOpportunityOceanConditionsV1} from '../../server.js';
export const source=readFileSync(new URL('../../server.js',import.meta.url),'utf8');
export const hash=s=>createHash('sha256').update(s).digest('hex');
export const names=['buildSurfaceWaterCharacterAnalysis','buildWaterMassAnalysis','buildMixingZoneAnalysis','buildEnvironmentalTransitionAnalysis','buildOceanFrontAnalysis','buildOceanPhysicsExplainabilitySummary','buildOceanPhysicsExplainabilityLineage','buildOceanOrganizationAnalysis'];
const acorn={};new Function('exports','module',process.binding('natives')['internal/deps/acorn/acorn/dist/acorn'])(acorn,{exports:acorn});
export function walk(n,visit){if(!n||typeof n!=='object')return;visit(n);for(const[k,v]of Object.entries(n)){if(['loc','start','end'].includes(k))continue;if(Array.isArray(v))v.forEach(x=>walk(x,visit));else if(v&&typeof v==='object')walk(v,visit);}}
function probe(n){if(n.type==='BlockStatement')return probe(n.body[0]);if(n.type==='ExpressionStatement')return probe(n.expression);if(n.type==='AssignmentExpression')return probe(n.right);if(n.type==='IfStatement')return n.test.start;return n.start;}
export function audit(){const ast=acorn.parse(source,{ecmaVersion:'latest',sourceType:'module',locations:true}),functions=[],consumers=[];for(const st of ast.body){const n=st.declaration??st;if(n.type!=='FunctionDeclaration')continue;const body=source.slice(n.start,n.end),fn=n.id.name;if(names.includes(fn)){const variables=[],decisions=[],inputs=new Set(),classifications=new Set(),identifiers=new Set(),calls=new Set();walk(n.body,x=>{if(x.type==='Identifier')identifiers.add(x.name);if(x.type==='CallExpression'||x.type==='NewExpression')calls.add(source.slice(x.callee.start,x.callee.end));if(x.type==='VariableDeclarator')variables.push({name:source.slice(x.id.start,x.id.end),expression:source.slice(x.init.start,x.init.end).replace(/\s+/g,' '),line:x.loc.start.line});if(x.type==='IfStatement'||x.type==='ConditionalExpression'){const p=source.slice(x.test.start,x.test.end).replace(/\s+/g,' '),id=fn+'::'+hash(p).slice(0,12)+'::'+decisions.filter(y=>y.predicate===p).length;decisions.push({id,kind:x.type,predicate:p,line:x.loc.start.line,start:x.start,end:x.end,consequent:{start:x.consequent.start,end:x.consequent.end,probe:probe(x.consequent)},alternate:x.alternate?{start:x.alternate.start,end:x.alternate.end,probe:probe(x.alternate)}:null});}if(x.type==='MemberExpression')inputs.add(source.slice(x.start,x.end).replace(/\s+/g,' '));if((x.type==='AssignmentExpression'&&x.left.type==='Identifier'&&x.left.name==='classification')||(x.type==='VariableDeclarator'&&x.id.name==='classification'))walk(x.right??x.init,y=>{if(y.type==='Literal'&&typeof y.value==='string')classifications.add(y.value);});});functions.push({name:fn,line:n.loc.start.line,sourceHash:hash(body),parameters:source.slice(n.params[0].start,n.params[0].end).replace(/\s+/g,' '),variables,decisions,identifiers:[...identifiers],calls:[...calls],memberReads:[...inputs],classifications:[...classifications],body});}else{const hits=[];walk(n.body,x=>{if(x.type==='MemberExpression'&&['oceanPhysics','oceanOrganization','surfaceWaterCharacter','waterMassAnalysis','mixingZoneAnalysis','environmentalTransitionAnalysis','oceanFrontAnalysis','oceanPhysicsExplainability'].includes(x.property?.name??x.property?.value))hits.push({line:x.loc.start.line,expression:source.slice(x.start,x.end).replace(/\s+/g,' ')});});if(hits.length)consumers.push({function:fn,line:n.loc.start.line,reads:hits});}}return {functions,consumers};}
export const thermalModes={uniform:{north:25,east:25,south:25,west:25},weak:{north:25.3,east:25,south:25,west:25},moderate:{north:26,east:25,south:25,west:25},strong:{north:28,east:27,south:24,west:25},partial:{north:28,east:null,south:null,west:25},missing:{north:null,east:null,south:null,west:null}};
export const currentModes={convergenceOnly:{north:[0,-.06],east:[-.06,0],south:[0,.06],west:[.06,0]},uniform:{all:[.5,.2]},edge:{north:[.5,.2],east:[2,0],south:[.5,.2],west:[.1,0]},shear:{north:[1,0],east:[.1,0],south:[-1,0],west:[.1,0]},convergence:{north:[0,-1],east:[-1,0],south:[0,1],west:[1,0]},divergence:{north:[0,1],east:[1,0],south:[0,-1],west:[-1,0]},rotation:{north:[1,0],east:[0,-1],south:[-1,0],west:[0,1]},zero:{all:[0,-0]},missing:{all:null}};
export const scenarios=Object.keys(thermalModes).flatMap(thermal=>Object.keys(currentModes).map(current=>({id:thermal+'--'+current,thermal,current,coordinates:[25,-90],center:thermal==='missing'?null:25}))).concat([{id:'all-missing',thermal:'missing',current:'missing',center:null,chlorophyll:null,coordinates:[25,-90]},{id:'chlorophyll-missing',thermal:'strong',current:'convergence',chlorophyll:null,coordinates:[25,-90]},{id:'stale-combined',thermal:'strong',current:'convergence',sourceTime:'2020-01-01T00:00:00Z',coordinates:[25,-90]},{id:'weather-rejected',thermal:'strong',current:'convergence',weatherRejected:true,coordinates:[25,-90]},{id:'chlorophyll-negative-zero',thermal:'uniform',current:'uniform',chlorophyll:-0,coordinates:[25,-90]},{id:'chlorophyll-positive-zero',thermal:'uniform',current:'uniform',chlorophyll:0,coordinates:[25,-90]}]);
export async function run(t,config={},clock=Date.parse('2300-01-01')){const {thermal='uniform',current='uniform',coordinates=[25,-90],center=25,chlorophyll=.1,sourceTime='2026-09-24T00:00:00Z',extras={}}=config;const [latitude,longitude]=coordinates,requests=[];const now=t.mock.method(Date,'now',()=>clock),warn=t.mock.method(console,'warn',()=>{});const transport=t.mock.method(globalThis,'fetch',async input=>{const u=new URL(input),weather=u.hostname==='api.open-meteo.com',marine=u.hostname==='marine-api.open-meteo.com',noaa=u.hostname.endsWith('.noaa.gov');assert(weather||marine||noaa,'Forbidden service');requests.push(String(u));if(weather&&config.weatherRejected)throw Error('Synthetic weather rejection');const decoded=decodeURIComponent(u.search),chl=decoded.includes('chlor_a');let lat=Number(u.searchParams.get('latitude')),lon=Number(u.searchParams.get('longitude'));if(noaa){const nums=[...decoded.matchAll(/\[\((-?\d+(?:\.\d+)?)\)\]/g)].map(x=>Number(x[1]));[lat,lon]=nums;}const role=lat>latitude?'north':lat<latitude?'south':lon>longitude?'east':lon<longitude?'west':'center';const uv=role==='center'?[.5,.2]:(currentModes[current].all??currentModes[current][role]);const currentMissing=current==='missing'||uv===null;const directional=marine&&u.searchParams.get('current')==='sea_surface_temperature';return {ok:true,json:async()=>noaa?{table:{columnNames:['time','latitude','longitude','chlor_a','u_current','v_current'],rows:(chl?chlorophyll===null:currentMissing)?[]:[[sourceTime,lat,lon,chlorophyll,...(uv??[null,null])]]}}:{latitude:lat,longitude:lon,current:{time:sourceTime,wind_speed_10m:4,wind_gusts_10m:6,wind_direction_10m:90,sea_surface_temperature:directional?thermalModes[thermal][role]:center,wave_height:1,wave_direction:90,wave_period:7,swell_wave_height:.5,swell_wave_direction:90,swell_wave_period:8}}};});try{const r=await evaluateUnifiedOpportunityOceanConditionsV1({...extras,assessment:{contractVersion:'pelora-scientific-assessment-v1',assessmentAt:'2026-09-26T01:00:00Z'},candidates:[{id:'physics-boundary',candidateClass:'open-water',coordinates,eligibility:{eligible:true}}],bearerToken:null,concurrency:1});const record=r.controlledEvaluation.evaluation.results[0];assert.equal(record.status,'fulfilled');return {ocean:record.value.oceanConditions,requests};}finally{transport.mock.restore();now.mock.restore();warn.mock.restore();}}
export function physical(ocean){return {oceanPhysics:ocean.observationSnapshot.oceanPhysics,oceanOrganization:ocean.observationSnapshot.oceanOrganization};}
export function leaves(value,path='',out=[]){if(value===null||typeof value!=='object'){out.push({path,type:value===null?'NULL':typeof value==='number'?(Object.is(value,-0)?'NUMBER_NEGATIVE_ZERO':value===0?'NUMBER_POSITIVE_ZERO':'NUMBER'):typeof value==='boolean'?'BOOLEAN':'STRING',value});return out;}for(const k of Object.keys(value))leaves(value[k],path+'/'+k,out);return out;}
export async function profiler(){const s=new Session();s.connect();const post=(m,p={})=>new Promise((resolve,reject)=>s.post(m,p,(e,v)=>e?reject(e):resolve(v)));await post('Profiler.enable');await post('Profiler.startPreciseCoverage',{callCount:true,detailed:true});return {async take(){return (await post('Profiler.takePreciseCoverage')).result.filter(x=>x.url.endsWith('/backend/server.js')).flatMap(x=>x.functions);},async close(){await post('Profiler.stopPreciseCoverage');s.disconnect();}};}
export function count(c,offset){const f=c.filter(x=>x.ranges[0].startOffset<=offset&&x.ranges[0].endOffset>offset).sort((a,b)=>(a.ranges[0].endOffset-a.ranges[0].startOffset)-(b.ranges[0].endOffset-b.ranges[0].startOffset))[0];if(f?.ranges[0].count>0)assert(f.isBlockCoverage,'Function-only coverage cannot prove branch execution');return c.flatMap(x=>x.ranges).filter(x=>x.startOffset<=offset&&x.endOffset>offset).sort((a,b)=>(a.endOffset-a.startOffset)-(b.endOffset-b.startOffset))[0]?.count??0;}
